ALTER TABLE employment_and_income ADD COLUMN fsi NUMERIC(5,3);
DO $$
BEGIN
    UPDATE employment_and_income AS e
    SET fsi = 0.3 * (1 - e.debincratio)
            + 0.3 * (a.liqassets / (e.mthincome * 6))
            + 0.2 * (a.bankaccbal / (e.mthincome * 3))
            + 0.2 * (a.savamount / (e.mthincome * 12))
    FROM expenses_and_assets AS a
    WHERE e.emplcoreref = a.expemplref;
END;
$$;
SELECT COUNT(fsi) AS computed_records, MIN(fsi), MAX(fsi) FROM employment_and_income;
ROLLBACK;

